def _sr_add(out,term,ids):
    for s in out:
        if s.get('term')==term:
            return
    out.append({'term':term,'support_ids':ids})

def _sr_add_text(xs,x):
    if x not in xs:
        xs.append(x)

def _sr_has(term,name):
    todo=[term]
    while todo:
        x=todo.pop()
        if isinstance(x,list) and x:
            if x[0]==name:
                return True
            i=1
            while i<len(x):
                if isinstance(x[i],list):
                    todo.append(x[i])
                i+=1
    return False

def _sr_text(span):
    x=span.get('text','')
    if isinstance(x,str):
        return x
    return str(x)

def _sr_candidate(raw):
    t=raw.casefold()
    return re.search(r'\b(return|returned|destroy|destroyed|retain|retained|retention|copies|copy)\b',t,re.I) is not None

def _sr_heading(raw):
    t=raw.casefold().strip()
    return len(t)<120 and (('return' in t and 'confidential' in t) or ('destruction' in t and 'confidential' in t))

def _sr_principal(raw):
    t=raw.casefold()
    if re.search(r'\b(shall|must|agrees|agree)\b',t,re.I) is None:
        return False
    return re.search(r'\b(return|returned|destroy|destroyed)\b',t,re.I) is not None

def _sr_linked(raw):
    t=raw.casefold().strip()
    return t.startswith('in lieu of return') or 'may retain' in t or 'backup system' in t or 'retention period' in t or t.startswith('in such an instance')

def _sr_window_ids(spans,i):
    ids=[]
    raw=_sr_text(spans[i])
    if i>0 and _sr_heading(_sr_text(spans[i-1])):
        ids.append(spans[i-1].get('id'))
    if _sr_linked(raw):
        j=i-1
        stop=i-5
        while j>=0 and j>=stop:
            if _sr_principal(_sr_text(spans[j])):
                if j>0 and _sr_heading(_sr_text(spans[j-1])):
                    x=spans[j-1].get('id')
                    if x not in ids:
                        ids.append(x)
                x=spans[j].get('id')
                if x not in ids:
                    ids.append(x)
                break
            j-=1
    x=spans[i].get('id')
    if x not in ids:
        ids.append(x)
    return ids

def _sr_candidates(spans):
    out=[]
    i=0
    while i<len(spans):
        raw=_sr_text(spans[i])
        if _sr_candidate(raw):
            out.append(_sr_window_ids(spans,i))
        i+=1
    return out

def _sr_queries(spans):
    ops=['disposal_retention_clause_role','disposal_retention_actor_role','principal_disposal_action','principal_disposal_trigger','principal_disposal_information_scope','retained_information_scope','disposal_retention_qualification','disposal_temporal_qualification']
    suffix=['role','actor','action','trigger','disposal_info','retention_info','qualification','timing']
    out=[]
    cs=_sr_candidates(spans)
    i=0
    while i<len(cs):
        j=0
        while j<len(ops):
            out.append({'id':'sr_'+str(i)+'_'+suffix[j],'operation':ops[j],'unit_ids':cs[i]})
            j+=1
        i+=1
    return out

def _sr_answers(xs,unresolved):
    out={}
    for a in xs:
        k=a.get('id')
        if k in out:
            unresolved.append('Duplicate semantic answer for '+str(k)+'.')
        else:
            out[k]=a
    return out

def _sr_get(answers,qid,op,unresolved,required):
    a=answers.get(qid)
    if a is None:
        if required:
            unresolved.append('Missing semantic judgment for '+qid+'.')
        return None
    if a.get('operation')!=op:
        if required:
            unresolved.append('Mismatched semantic operation for '+qid+'.')
        return None
    c=a.get('choice','unknown')
    if c=='unknown':
        if required:
            unresolved.append('The source judgment remains unknown for '+qid+'.')
        return None
    return c

def _sr_window(spans,ids):
    texts=[]
    found=[]
    for wanted in ids:
        for s in spans:
            if s.get('id')==wanted:
                texts.append(_sr_text(s))
                found.append(wanted)
                break
    return ' '.join(texts),found

def _sr_named_actor(raw):
    m=re.search(r'\b([A-Z][A-Za-z0-9_-]{0,40})\s+(?:further\s+)?agrees\b',raw)
    if m is not None:
        return m.group(1)
    m=re.search(r'\b([A-Z][A-Za-z0-9_-]{0,40})\s+shall\b',raw)
    if m is not None:
        return m.group(1)
    return None

def _sr_actor(choice,raw,unresolved,qid):
    if choice in ('designated_recipient_holder','contextual_party_as_holder'):
        return ['receiving_party']
    if choice=='holder_and_its_representatives':
        return ['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
    if choice=='named_service_actor':
        x=_sr_named_actor(raw)
        if x is not None:
            return ['named_recipient',x]
        unresolved.append('The named disposal actor could not be copied safely from '+qid+'.')
        return None
    unresolved.append('No representable operative actor was obtained for '+qid+'.')
    return None

def _sr_disposal_info(choice):
    ci=['confidential_information']
    cp=['copies_of',['confidential_information']]
    if choice=='confidential_information_only':
        return ci
    if choice=='confidential_information_and_all_copies':
        return ['information_bundle',ci,cp]
    if choice=='all_copies_of_confidential_information':
        return cp
    if choice=='confidential_information_copies_and_derivatives':
        return ['information_bundle',ci,['information_bundle',cp,['derivative_materials_of',['confidential_information']]]]
    return None

def _sr_retention_info(choice):
    if choice in ('single_archival_copy','law_required_record_copy','backup_system_confidential_information'):
        return ['copies_of',['confidential_information']]
    if choice=='all_copies_and_stated_derivatives':
        return ['information_bundle',['copies_of',['confidential_information']],['derivative_materials_of',['confidential_information']]]
    if choice=='confidential_information_generally':
        return ['confidential_information']
    return None

def _sr_trigger(choice):
    if choice=='service_termination':
        return ['service_termination']
    if choice=='agreement_termination':
        return ['agreement_termination']
    if choice=='purpose_completion_or_supplier_request':
        return ['trigger_alternative',['purpose_completion'],['request_by',['disclosing_party']]]
    if choice=='agreement_termination_or_supplier_request_earlier':
        return ['trigger_alternative',['agreement_termination'],['request_by',['disclosing_party']]]
    if choice=='supplier_request':
        return ['request_by',['disclosing_party']]
    return None

def _sr_action(choice,info,unresolved,qid):
    ret=['return_to',info,['disclosing_party']]
    des=['destroy',info]
    if choice=='return_to_information_supplier':
        return ret
    if choice=='destroy_only':
        return des
    if choice=='return_or_destroy_holder_election':
        return ['action_alternative',ret,des]
    if choice=='return_or_destroy_supplier_election':
        unresolved.append('The supplier-controlled election between return and destruction is preserved as unresolved choice allocation for '+qid+'.')
        return ['action_alternative',ret,des]
    if choice=='destroy_in_lieu_with_certification':
        unresolved.append('The written certification accompanying destruction in lieu of return is not representable by the available constructors for '+qid+'.')
        return ['action_alternative',ret,des]
    return None

def _sr_retention_condition(qual):
    if qual=='archival_copy_retention':
        return ['retention_condition','one copy solely for archival purpose']
    if qual=='law_required_record_copy_retention':
        return ['retention_condition','record copy required by applicable law']
    return None

def _sr_exceptions(qual,actor,rinfo):
    if qual=='no_express_exception_or_retention':
        return ['no_exceptions']
    if qual=='different_written_instructions_exception':
        return ['exception_set',['authorization_exception','different written instructions from the information-supplying participant']]
    cond=_sr_retention_condition(qual)
    if cond is not None and rinfo is not None:
        return ['exception_set',['retention_exception',actor,rinfo,cond]]
    return None

def _sr_support(ids):
    out=[]
    for x in ids:
        if x is not None and x not in out:
            out.append(x)
    return out

def _sr_timing(choice,unresolved,qid):
    if choice in ('no_additional_timing','no_disposal_timing_context'):
        return
    if choice=='within_one_month_after_trigger':
        unresolved.append('The one-month disposal deadline is source-grounded but not representable by the available disposal constructor for '+qid+'.')
    elif choice=='within_ten_business_days':
        unresolved.append('The ten-business-day disposal deadline is source-grounded but not representable by the available disposal constructor for '+qid+'.')
    elif choice=='immediate_and_not_later_than_ten_days_earlier_event':
        unresolved.append('The immediate/ten-day deadline and earlier-event priority are source-grounded but not fully representable by the available constructors for '+qid+'.')
    elif choice=='regular_records_retention_schedule':
        unresolved.append('The regular records-retention destruction schedule requires a linked effect not representable as a standalone common59 norm for '+qid+'.')
    elif choice=='retention_until_legal_period_expires':
        unresolved.append('The retention-expiry return/destruction duty requires a linked temporal effect not representable as a standalone common59 norm for '+qid+'.')
    else:
        unresolved.append('Unsupported temporal qualification for '+qid+'.')

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    queries=_sr_queries(spans)
    if inputs.get('phase')=='plan':
        return {'queries':queries}
    statements=[]
    refs=[]
    texts=[]
    ids=[]
    for s in spans:
        raw=_sr_text(s)
        texts.append(raw)
        ids.append(s.get('id'))
        parse_context(raw,[s.get('id')],statements,refs)
    i=0
    while i+1<len(texts):
        w=texts[i]+' '+texts[i+1]
        lw=w.casefold()
        if ('restrict access' in lw and 'such employees' in lw) or ('neither it nor its representatives' in lw and ('any other person' in lw or 'other person or organization' in lw)):
            parse_context(w,[ids[i],ids[i+1]],statements,refs)
        i+=1
    unresolved=[]
    answers=_sr_answers(inputs.get('semantic_answers',[]),unresolved)
    cs=_sr_candidates(spans)
    i=0
    while i<len(cs):
        base='sr_'+str(i)+'_'
        role=_sr_get(answers,base+'role','disposal_retention_clause_role',unresolved,True)
        if role is None:
            i+=1
            continue
        if role=='no_relevant_operative_effect':
            i+=1
            continue
        timing=_sr_get(answers,base+'timing','disposal_temporal_qualification',unresolved,role!='no_relevant_operative_effect')
        if role=='supplemental_linked_effect':
            if timing is not None:
                _sr_timing(timing,unresolved,base+'timing')
            unresolved.append('A linked disposal or retention effect could not be represented safely for '+base+'role.')
            i+=1
            continue
        raw,support=_sr_window(spans,cs[i])
        actor_choice=_sr_get(answers,base+'actor','disposal_retention_actor_role',unresolved,True)
        actor=None
        if actor_choice is not None:
            actor=_sr_actor(actor_choice,raw,unresolved,base+'actor')
        qual=_sr_get(answers,base+'qualification','disposal_retention_qualification',unresolved,True)
        if timing is not None:
            _sr_timing(timing,unresolved,base+'timing')
        needs_disposal=role in ('operative_disposal','operative_disposal_and_retention_permission')
        needs_retention=role in ('operative_retention_permission','operative_retention_prohibition','operative_disposal_and_retention_permission')
        dinfo=None
        rinfo=None
        if needs_disposal:
            dc=_sr_get(answers,base+'disposal_info','principal_disposal_information_scope',unresolved,True)
            if dc is not None:
                dinfo=_sr_disposal_info(dc)
            if dinfo is None:
                unresolved.append('The principal disposal information scope could not be represented for '+base+'disposal_info.')
        if needs_retention:
            rc=_sr_get(answers,base+'retention_info','retained_information_scope',unresolved,True)
            if rc is not None:
                rinfo=_sr_retention_info(rc)
            if rinfo is None:
                unresolved.append('The retained-information scope could not be represented for '+base+'retention_info.')
        if needs_disposal and actor is not None and dinfo is not None:
            ac=_sr_get(answers,base+'action','principal_disposal_action',unresolved,True)
            tc=_sr_get(answers,base+'trigger','principal_disposal_trigger',unresolved,True)
            action=None
            trigger=None
            if ac is not None:
                action=_sr_action(ac,dinfo,unresolved,base+'action')
            if tc is not None:
                trigger=_sr_trigger(tc)
                if tc=='linked_prior_disposal_trigger':
                    unresolved.append('The principal trigger is linked to a governing duty and was not reconstructed by lexical fallback for '+base+'trigger.')
            ex=None
            if qual is not None:
                ex=_sr_exceptions(qual,actor,rinfo)
            if action is None:
                unresolved.append('The principal disposal action could not be represented for '+base+'action.')
            if trigger is None:
                unresolved.append('The principal disposal trigger could not be represented for '+base+'trigger.')
            if ex is None:
                unresolved.append('The disposal exceptions could not be represented for '+base+'qualification.')
            if action is not None and trigger is not None and ex is not None:
                _sr_add(statements,['disposal_obligation',actor,action,trigger,ex],_sr_support(support))
        if role in ('operative_retention_permission','operative_disposal_and_retention_permission') and actor is not None and rinfo is not None:
            cond=None
            if qual is not None:
                cond=_sr_retention_condition(qual)
            if cond is None:
                unresolved.append('The retention permission condition could not be represented for '+base+'qualification.')
            else:
                _sr_add(statements,['retention_permission',actor,rinfo,['after_disposal'],cond],_sr_support(support))
        if role=='operative_retention_prohibition' and actor is not None and rinfo is not None:
            if qual!='express_no_retention':
                unresolved.append('The retention prohibition qualification is inconsistent or unknown for '+base+'qualification.')
            else:
                _sr_add(statements,['retention_prohibition',actor,rinfo,['after_disposal']],_sr_support(support))
        i+=1
    has_permission=False
    has_definition=False
    needs_definition=False
    for s in statements:
        term=s.get('term')
        if isinstance(term,list) and term:
            if term[0]=='permission' or _sr_has(term,'permission_exception'):
                has_permission=True
            if term[0]=='define_representative':
                has_definition=True
            if term[0] in ('permission','prohibition') and _sr_has(term,'representatives_of'):
                needs_definition=True
    if refs and not has_permission:
        unresolved.append('A disclosure exception refers to another provision, but no operative recipient permission was resolved from the current source.')
    if needs_definition and not has_definition:
        unresolved.append('An operative disclosure norm uses Representatives, but their current-source membership or owner binding was not resolved.')
    return {'statements':statements,'complete':not unresolved,'unresolved':unresolved}
